REM {Il faut utiliser une vue dans laquelle une colonne contient les UNIDs};
v_Cle :=Tabl_Nom;
v_NomVue := "V_Tabl20";
v_NoColonneUNID := 9;

@If(v_Cle = NULL; @Return(@Failure("Le nom est obligatoire.")); "");
v_Lookup := @DbLookup("" : "NoCache"; ""; v_NomVue; v_Cle; v_NoColonneUNID);
@If(@IsError(v_Lookup); @Success; @Elements(v_Lookup) = 1 & v_Lookup = @Text(@DocumentUniqueID); @Success; @Failure("La table est déjà définie."))

v_Cle := SICT_Nom;
v_NomVue := "V_SICT20";

@If(v_Cle = NULL; @Return(@Failure("Le nom est obligatoire.")); "");
v_Lookup := @DbLookup("" : "NoCache"; ""; v_NomVue; v_Cle; 1; [ReturnDocumentUniqueID]);
@If(@IsError(v_Lookup); @Success; @Elements(v_Lookup) = 1 & v_Lookup = @Text(@DocumentUniqueID); @Success; @Failure("Le courriel est déjà défini."))

v_NomVue := "V_Depa20";

@If(@IsNull(@ThisValue ); @Return(@Failure("Le numéro du département est obligatoire.")); "");
v_Lookup := @DbLookup("" : "NoCache"; ""; v_NomVue; @ThisValue; 1; [ReturnDocumentUniqueID]);
@If(@IsError(v_Lookup); @Success; @Elements(v_Lookup) = 1 & v_Lookup = @Text(@DocumentUniqueID); @Success; @Failure("Le numéro du département est déjà défini."))

v_NomTable := "ISO639-1xFR";
v_Cle := Repr_Langue;

@Replace(v_Cle; @IfError(@DbLookup(""; SF_GDK; "V_Tabl20"; v_NomTable; 4); ""); @IfError(@DbLookup(""; SF_GDK; "V_Tabl20"; v_NomTable; 5); ""))
